// What people wear, shared by the people with faces and the visitors who are only their clothes: loose sweaters,
// hoodies, open overshirts and tees over wide trousers or a short skirt, and trainers. `at` is where they stand
// (bottom-centre) and `k` their scale. Composition comes from `r` (the shape stream), never from the pen.
import { add, arc, dot, lerp, length, turn, type Point } from "../geometry"
import type { Sheet } from "../layers"
import type { Stream } from "../seed"
import type { Pen } from "../stroke"

/** Tops anybody can wear; a tee shows bare arms, so only people with faces wear one. */
export const TOPS = ["sweater", "hoodie", "overshirt", "tee"]

// Sleeve and arm cuts from the shoulder: u runs outwards, v down the arm. Points 1 and 2 are the cuff.
const LONG: Point[] = [
  [8.5, 27],
  [11.5, 51],
  [0.5, 53],
  [-5.5, 23],
]
const SHORT: Point[] = [
  [7.5, 10],
  [10, 21.5],
  [-1.5, 23.5],
  [-5, 12],
]
const ARM: Point[] = [
  [7, 14],
  [9, 50],
  [2, 51.5],
  [-3.5, 15],
]

/** A sleeve or arm hanging from shoulder S, swung by a degrees; returns its outline, cuff and where the hand goes. */
function limb(S: Point, side: number, k: number, a: number, cut: Point[]) {
  const pts = cut.map(([u, v]) =>
    turn([S[0] + side * u * k, S[1] + v * k], S, a),
  )
  const [a0, a1, a2, a3] = pts as [Point, Point, Point, Point]
  const cuff: Point = lerp(a1, a2, 0.5)
  const out: Point = [
    cuff[0] - (a0[0] + a3[0]) / 2,
    cuff[1] - (a0[1] + a3[1]) / 2,
  ]
  const len = length(out) || 1
  const [b0, b1] = [lerp(a0, a1, 0.8), lerp(a3, a2, 0.8)]
  return {
    outline: [S, ...pts],
    band: [lerp(b0, b1, 0.15), lerp(b0, b1, 0.85)] as const,
    hand: add(cuff, out, (4.5 * k) / len),
  }
}

/** What someone wears: a pose, a top, a bottom, how far apart the feet are, and whether anybody is inside. */
export interface Outfit {
  pose?: string
  top?: string
  bottom?: string
  stride?: number
  nobody?: boolean
}

/** The whole outfit, back to front: hood, trainers, trousers or skirt, the top and its sleeves. Returns the hands. */
export function clothes(
  s: Sheet,
  p: Pen,
  r: Stream,
  at: Point,
  k: number,
  {
    pose = "stand",
    top = "sweater",
    bottom = "trousers",
    stride = 0,
    nobody = false,
  }: Outfit = {},
) {
  const [x, y] = at
  const P = (u: number, v: number): Point => [x + u * k, y + v * k]
  const path = (pts: [number, number][]) => pts.map(([u, v]) => P(u, v))
  const ribbed = top === "sweater" || top === "hoodie"
  if (top === "hoodie") {
    // The hood lies on the shoulders behind the neck; the body hides its lower half.
    const hood = path([
      [-16, -154],
      ...arc([0, -161], 15, 9, 180, 360, 10),
      [16, -154],
    ])
    s.blank(p.shape(hood))
    s.stroke(p.path(hood))
  }
  // Trainers: a rounded toe and a sole line, under the trouser hems.
  for (const side of [-1, 1]) {
    const fx = side * (10 + stride)
    const shoe = [
      P(fx - 8, 0),
      P(fx + 8, 0),
      ...arc([fx, -3], 8, 4.6, 0, -180, 8).map(([u, v]) => P(u, v)),
    ]
    s.blank(p.shape(shoe))
    s.stroke(p.shape(shoe))
    s.stroke(p.line(P(fx - 7.6, -1.8), P(fx + 7.6, -1.8)))
  }
  if (bottom === "skirt") {
    for (const side of [-1, 1])
      for (const dx of [5, 11])
        s.stroke(
          p.line(P(side * (dx + stride / 2), -52), P(side * (dx + stride), -5)),
        )
    const skirt = path([
      [-17, -90],
      [-25, -52],
      [25, -52],
      [17, -90],
    ])
    s.blank(p.shape(skirt))
    s.stroke(p.shape(skirt))
  } else {
    const legs = path([
      [-17, -90],
      [-19.5 - stride, -6],
      [-3 - stride, -6],
      [0, -60],
      [3 + stride, -6],
      [19.5 + stride, -6],
      [17, -90],
    ])
    s.blank(p.shape(legs))
    s.stroke(p.path(legs))
    // Rolled-up hems.
    for (const side of [-1, 1])
      s.stroke(
        p.line(P(side * (16.8 + stride), -13), P(side * (5.8 + stride), -13)),
      )
  }
  const body = path([
    [-8, -163],
    [-23, -154],
    [-19, -130],
    [-21.5, -87],
    [21.5, -87],
    [19, -130],
    [23, -154],
    [8, -163],
  ])
  s.blank(p.shape(body))
  s.stroke(p.path(body))
  const neck = path(arc([0, -163], 8, 4, 0, 180, 8) as [number, number][])
  if (top === "overshirt") {
    // An open shirt over a tee: the tee's neckline, two lapels and the shirt's fronts falling apart.
    s.stroke(p.path(neck))
    for (const side of [-1, 1]) {
      s.stroke(
        p.path(
          path([
            [side * 8, -163],
            [side * 13, -150],
            [side * 5, -147],
          ]),
        ),
      )
      s.stroke(
        p.path(
          path([
            [side * 5, -147],
            [side * 6.5, -118],
            [side * 7, -87],
          ]),
        ),
      )
    }
    s.stroke(
      p.shape(
        path([
          [-17, -142],
          [-10, -142],
          [-10, -133],
          [-17, -133],
        ]),
      ),
    )
  } else {
    s.stroke(p.path(neck))
    // Bands sit a little inside the outline, so a run past their ends stays on the cloth.
    if (ribbed) s.stroke(p.line(P(-18, -93), P(18, -93)))
  }
  if (top === "hoodie") {
    s.stroke(
      p.path(
        path([
          [-13, -112],
          [-10, -97],
          [10, -97],
          [13, -112],
          [-13, -112],
        ]),
      ),
    )
    for (const side of [-1, 1])
      s.stroke(p.line(P(side * 3.5, -160), P(side * 4.5, -141)))
  }
  // Every pose's swing is drawn, in this order, whichever pose is used, so the draws after it stay put.
  const stand: Point = [r.signed() * 5, r.signed() * 5]
  const swings: Record<string, Point> = {
    stand,
    wave: [r.signed() * 5, -155],
    mug: [r.signed() * 5, 52],
    walk: [14, -12],
    // Both hands down in front, into a bin of records. Fixed, so it takes nothing from the stream.
    browse: [-11, 11],
  }
  const swing = swings[pose] ?? stand
  const hands = [-1, 1].map((side, i) => {
    const S = P(side * 22, -155)
    const a = swing[i] as number
    const short = top === "tee" && !nobody
    const sl = limb(S, side, k, a, short ? SHORT : LONG)
    const arm = limb(S, side, k, a, ARM)
    if (short) {
      // The bare arm, its top tucked up under the short sleeve drawn next.
      s.blank(p.shape(arm.outline))
      s.stroke(p.path(arm.outline.slice(1)))
    }
    s.blank(p.shape(sl.outline))
    s.stroke(p.path([...sl.outline, sl.outline[0] as Point]))
    if (ribbed) s.stroke(p.line(...sl.band))
    return short ? arm.hand : sl.hand
  })
  for (const h of nobody ? [] : hands) {
    s.blank(p.disc(...dot(h, 3.6 * k)))
    s.stroke(p.ring(...dot(h, 3.6 * k)))
  }
  return { hands, neck: P(0, -163) }
}

// People with faces, and portraits for avatars. `at` is where they stand (bottom-centre) unless a function says
// otherwise; `k` is their scale. Composition comes from `r` (the shape stream), never from the pen, so takes agree.
import { add, arc, dot, roundRect, type Point } from "../geometry"
import { define, type Draw, objectsIn } from "../library"
import type { Sheet } from "../layers"
import type { Pen } from "../stroke"
import { clothes, TOPS } from "./clothes"
import { mug } from "./parts"

/** Hair is a pocket of ink: drawn as an outline it reads as grey. */
export const HAIR = [
  "bob",
  "crop",
  "fringe",
  "bun",
  "curls",
  "long",
  "ponytail",
  "waves",
]

/** Points on a head centred at `c`: u across, v down, both scaled by k. */
const onHead = (c: Point, k: number) => ({
  P: (u: number, v: number): Point => [c[0] + u * k, c[1] + v * k],
  A: (rx: number, ry: number, a0: number, a1: number, n = 14, dy = 0) =>
    arc([0, dy], rx, ry, a0, a1, n).map(([u, v]): Point => [
      c[0] + u * k,
      c[1] + v * k,
    ]),
})

/** The hair that falls behind the head and shoulders: long hair, a ponytail, a fringe's back. Draw before the clothes. */
export function hairBehind(
  s: Sheet,
  p: Pen,
  c: Point,
  k: number,
  hair: string,
) {
  const { P, A } = onHead(c, k)
  const fall = ({ long: 32, fringe: 13 } as Record<string, number>)[hair]
  if (fall)
    s.fill(p.shape([P(-15, fall), ...A(15.5, 19, 160, 380, 18), P(15, fall)]))
  if (hair === "ponytail")
    s.fill(
      p.shape([
        P(7, -12),
        P(17, -10),
        P(22, 2),
        P(20, 22),
        P(16, 12),
        P(12, 0),
      ]),
    )
}

/** A face centred at `c` with its hair in front: ears, features, glasses and a beard, all from the seed unless given. */
export const head: Draw = (
  s,
  p,
  r,
  c,
  k = 1,
  { hair = r.pick(HAIR), glasses = r.chance(0.3), beard = r.chance(0.15) } = {},
) => {
  const { P, A } = onHead(c, k)
  s.stroke(p.line(P(-4, 12), P(-4, 15.5)))
  s.stroke(p.line(P(4, 12), P(4, 15.5)))
  s.blank(p.disc(c, [12 * k, 0], [0, 15 * k]))
  s.stroke(p.ring(c, [12 * k, 0], [0, 15 * k]))
  if (["crop", "bun", "ponytail", "waves"].includes(hair)) {
    s.stroke(
      p.path(A(2.6, 3.6, 270, 450, 6).map((pt) => add(pt, [12 * k, 2 * k]))),
    )
    s.stroke(
      p.path(A(2.6, 3.6, 90, 270, 6).map((pt) => add(pt, [-12 * k, 2 * k]))),
    )
  }
  // A cap of hair over the crown, its hairline given as points from the right temple to the left.
  const cap = (rx: number, ry: number, line: [number, number][]) =>
    s.fill(
      p.shape([...A(rx, ry, 180, 360, 14), ...line.map(([u, v]) => P(u, v))]),
    )
  if (hair === "bob")
    s.fill(
      p.shape([
        P(-14.5, 11),
        ...A(15, 18, 170, 370, 16),
        P(14.5, 11),
        P(11, 11),
        P(11, -4),
        P(-11, -4),
        P(-11, 11),
      ]),
    )
  else if (hair === "crop")
    cap(13, 16.5, [
      [12.6, -3],
      [9, -7],
      [4, -5],
      [-2, -8],
      [-8, -5],
      [-12.6, -3],
    ])
  else if (hair === "bun" || hair === "ponytail") {
    cap(13, 16.3, [
      [12.8, -1],
      [7, -6.5],
      [0, -8],
      [-7, -6.5],
      [-12.8, -1],
    ])
    if (hair === "bun") s.fill(p.disc(...dot(P(1, -19), 6 * k)))
  } else if (hair === "waves") {
    // Short and a little tousled: the crown's outline swells and dips.
    const crown = Array.from({ length: 13 }, (_, i): Point => {
      const [f, a] = [i % 2 ? 1.07 : 1, 190 + (i * 160) / 12]
      return A(14 * f, 18.5 * f, a, a, 1)[0] as Point
    })
    s.fill(
      p.shape([
        ...crown,
        P(12.6, -2),
        P(7, -8),
        P(1, -6),
        P(-5, -9),
        P(-12.6, -1),
      ]),
    )
  } else if (hair === "curls") {
    cap(13, 16, [
      [12.5, -1],
      [6, -6],
      [-6, -6],
      [-12.5, -1],
    ])
    for (let a = 170; a <= 370; a += 25)
      s.fill(p.disc(...dot(A(13.5, 16.5, a, a, 1)[0] as Point, 5 * k)))
  } else if (hair === "long" || hair === "fringe") {
    // Parted: each side falls from the crown past the cheeks.
    const low = hair === "long" ? 12 : 9
    s.fill(
      p.shape([
        P(-12.8, low),
        ...A(13.5, 16.5, 180, 360, 14),
        P(12.8, low),
        P(10.6, low - 1),
        P(10, -3),
        P(4, -8.5),
        P(0, -11),
        P(-4, -8.5),
        P(-10, -3),
        P(-10.6, low - 1),
      ]),
    )
  }
  if (glasses) {
    for (const side of [-1, 1])
      s.stroke(
        p.shape(
          roundRect(
            c[0] + (side * 5.2 - 4.4) * k,
            c[1] - 2.6 * k,
            8.8 * k,
            7.2 * k,
            2.6 * k,
          ),
        ),
      )
    s.stroke(p.line(P(-0.9, 0.4), P(0.9, 0.4)))
  }
  for (const side of [-1, 1]) s.fill(p.disc(...dot(P(side * 5, 1), 1.15 * k)))
  s.stroke(p.path([P(0.6, 2), P(-1.4, 7.2), P(1.4, 7.6)]))
  if (beard && !["long", "bob", "fringe"].includes(hair))
    s.fill(
      p.shape([
        P(-12, 3),
        ...A(12.5, 16.5, 170, 10, 14),
        P(12, 3),
        P(5, 9),
        P(-5, 9),
      ]),
    )
  else s.stroke(p.path(A(3.4, 1.8, 20, 160, 6, 10.5)))
}

/** A person standing, waving or holding a mug, in everyday clothes. */
export const person: Draw = (
  s,
  p,
  r,
  at,
  k = 1,
  {
    pose = r.pick(["stand", "wave", "mug"]),
    hair = r.pick(HAIR),
    glasses,
    beard,
  } = {},
) => {
  const picked = r.pick(TOPS)
  // A hood would sit over long hair.
  const top = picked === "hoodie" && hair === "long" ? "sweater" : picked
  const bottom = r.chance(0.3) ? "skirt" : "trousers"
  const c: Point = [at[0], at[1] - 178 * k]
  hairBehind(s, p, c, k, hair)
  const { hands } = clothes(s, p, r, at, k, {
    pose,
    top,
    bottom,
    stride: r.signed() * 2,
  })
  head(s, p, r, c, k, { hair, glasses, beard })
  if (pose === "mug")
    mug(s, p, r, add(hands[1] as Point, [-3 * k, 4 * k]), 0.45 * k, {})
}

export const personWave: Draw = (s, p, r, at, k) =>
  person(s, p, r, at, k, { pose: "wave" })

export const personMug: Draw = (s, p, r, at, k) =>
  person(s, p, r, at, k, { pose: "mug" })

/** Head and shoulders, for avatars: `at` is the centre of the tile. */
export const portrait: Draw = (s, p, r, at, k = 1, options = {}) => {
  const P = (u: number, v: number): Point => [at[0] + u * k, at[1] + v * k]
  const hair = options.hair ?? r.pick(HAIR)
  const top = r.pick(TOPS)
  const shoulders = [
    P(-36, 46),
    P(-31, 26),
    P(-12, 16),
    P(12, 16),
    P(31, 26),
    P(36, 46),
  ]
  hairBehind(s, p, P(0, 1), k, hair)
  if (top === "hoodie")
    s.stroke(p.path(arc([0, 20], 17, 8, 200, 340, 8).map(([u, v]) => P(u, v))))
  // Long hair falls behind the shoulders, not over the chest.
  s.blank(p.shape(shoulders))
  s.stroke(p.path(shoulders))
  s.stroke(p.path(arc([0, 16], 8, 5, 0, 180, 8).map(([u, v]) => P(u, v))))
  if (top === "overshirt")
    for (const side of [-1, 1])
      s.stroke(
        p.path([
          P(side * 8, 17),
          P(side * 15, 30),
          P(side * 6, 33),
          P(side * 7, 46),
        ]),
      )
  if (top === "hoodie")
    for (const side of [-1, 1])
      s.stroke(p.line(P(side * 3.5, 21), P(side * 4.5, 40)))
  head(s, p, r, P(0, 1), k, { ...options, hair })
}

const T = objectsIn("people")

define(
  T("person", "Person", [118, 262], [57, 252], 1.15, person, [
    "person",
    "team",
    "customer",
  ]),
  T("person-wave", "Waving", [118, 262], [57, 252], 1.15, personWave, [
    "person",
    "greeting",
    "welcome",
  ]),
  T("person-mug", "With a mug", [118, 262], [57, 252], 1.15, personMug, [
    "person",
    "break",
    "coffee",
  ]),
  T("portrait", "Portrait", [100, 100], [50, 46], 1, portrait, [
    "avatar",
    "profile",
    "account",
  ]),
)

// Someone at work, seen from behind on an office chair: the back of a sweater, hoodie, open shirt or tee above the
// backrest, elbows out to either side, then the chair's seat, column and five-star base in front of them. The visitor
// is only their clothes; the person shows the back of their head. `at` is the floor under the chair's column.
import { add, arc, dot, length, roundRect, type Point } from "../geometry"
import { define, type Draw, objectsIn } from "../library"
import type { Sheet } from "../layers"
import type { Pen } from "../stroke"
import { TOPS } from "./clothes"
import { HAIR } from "./faces"

type Place = (u: number, v: number) => Point
const pts = (P: Place, list: [number, number][]) =>
  list.map(([u, v]) => P(u, v))

/** The office chair from behind, drawn over whoever sits in it: seat, backrest, column and base. */
function chair(s: Sheet, p: Pen, P: Place, k: number, high: number) {
  const R = (u: number, v: number, w: number, h: number, rad: number) =>
    roundRect(...P(u, v), w * k, h * k, rad * k)
  const part = (outline: Point[]) => {
    s.blank(p.shape(outline))
    s.stroke(p.shape(outline))
  }
  part(R(-33, -60, 66, 11, 5))
  part(
    pts(P, [
      [-4.5, -74],
      [4.5, -74],
      [4.5, -59],
      [-4.5, -59],
    ]),
  )
  part(R(-21, -116 - high, 42, 44 + high, 12))
  s.stroke(p.shape(R(-17, -112 - high, 34, 36 + high, 8.5)))
  // Five legs round the hub, seen a little from above: the two pointing away go behind the column.
  const hub: Point = [0, -18]
  const leg = (a: number) => {
    const tip = arc(hub, 34, 10, a, a, 1)[0] as Point
    const len = length([tip[0], tip[1] - hub[1]]) || 1
    const side: Point = [((hub[1] - tip[1]) / len) * 1.6, (tip[0] / len) * 1.6]
    part(
      pts(P, [
        add(hub, side, -1),
        add(tip, side, -0.7),
        add(tip, side, 0.7),
        add(hub, side),
      ]),
    )
    s.stroke(p.line(P(tip[0], tip[1] + 1), P(tip[0], tip[1] + 3)))
    s.blank(p.disc(...dot(P(tip[0], tip[1] + 5.5), 3 * k)))
    s.stroke(p.ring(...dot(P(tip[0], tip[1] + 5.5), 3 * k)))
  }
  leg(234)
  leg(-54)
  part(
    pts(P, [
      [-2.4, -49],
      [2.4, -49],
      [2.4, -34],
      [-2.4, -34],
    ]),
  )
  part(
    pts(P, [
      [-4, -34],
      [4, -34],
      [4, -19],
      [-4, -19],
    ]),
  )
  for (const a of [162, 18, 90]) leg(a)
}

/** The back of a head centred at `c`: the hair covers the crown and stops at the nape, the ears stand out of it. */
function backOfHead(s: Sheet, p: Pen, P: Place, k: number, hair: string) {
  const A = (rx: number, ry: number, a0: number, a1: number) =>
    arc([0, -160], rx, ry, a0, a1, 14).map(([u, v]) => P(u, v))
  s.stroke(p.line(P(-4, -145), P(-4, -139)))
  s.stroke(p.line(P(4, -145), P(4, -139)))
  s.blank(p.disc(P(0, -160), [12 * k, 0], [0, 15 * k]))
  s.stroke(p.ring(P(0, -160), [12 * k, 0], [0, 15 * k]))
  const nape = pts(P, [
    [12.5, -155],
    [6, -150.5],
    [0, -149.5],
    [-6, -150.5],
    [-12.5, -155],
  ])
  if (hair === "bob" || hair === "fringe") {
    const hem = hair === "bob" ? -148 : -151
    s.fill(p.shape([...A(15, 18, 165, 375), P(14.5, hem), P(-14.5, hem)]))
  } else if (hair === "long")
    s.fill(
      p.shape([
        ...A(15.5, 19, 160, 380),
        ...pts(P, [
          [16, -126],
          [5, -124],
          [-5, -125],
          [-16, -126],
        ]),
      ]),
    )
  else if (hair === "waves") {
    const crown = Array.from({ length: 13 }, (_, i): Point => {
      const [f, a] = [i % 2 ? 1.07 : 1, 175 + (i * 190) / 12]
      return A(13.5 * f, 18 * f, a, a)[0] as Point
    })
    s.fill(p.shape([...crown, ...nape]))
  } else s.fill(p.shape([...A(13, 16.5, 175, 365), ...nape]))
  if (hair === "curls")
    for (let a = 165; a <= 375; a += 25)
      s.fill(p.disc(...dot(A(13.5, 16.5, a, a)[0] as Point, 5 * k)))
  if (hair === "bun") s.fill(p.disc(...dot(P(0, -177), 6.5 * k)))
  if (hair === "ponytail")
    s.fill(
      p.shape(
        pts(P, [
          [-3, -156],
          [3, -156],
          [4.5, -141],
          [1, -130],
          [-2.5, -140],
        ]),
      ),
    )
  if (["crop", "bun", "ponytail", "waves"].includes(hair))
    for (const side of [-1, 1]) {
      const from = side > 0 ? -90 : 90
      const ear = arc([side * 12.5, -158], 2.8, 4, from, from + 180, 6)
      s.blank(p.shape(pts(P, ear as [number, number][])))
      s.stroke(p.path(pts(P, ear as [number, number][])))
    }
}

/** Seated from behind; `hair` gives the person a head, without it they are only their clothes. */
const seated = (withHead: boolean): Draw =>
  function sitter(s, p, r, at, k = 1, options = {}) {
    const P: Place = (u, v) => [at[0] + u * k, at[1] + v * k]
    const top = r.pick(withHead ? TOPS : TOPS.slice(0, 3))
    const hair = options.hair ?? r.pick(HAIR)
    const high = r.between(0, 8)
    const reach = [r.between(0, 4), r.between(0, 4)]
    const torso = pts(P, [
      [-8, -141],
      [-25, -133],
      [-24, -108],
      [-25, -62],
      [25, -62],
      [24, -108],
      [25, -133],
      [8, -141],
    ])
    s.blank(p.shape(torso))
    s.stroke(p.shape(torso))
    // Elbows bent out to either side, the forearms going on to the desk out of sight.
    for (const [i, side] of [-1, 1].entries()) {
      const out = reach[i] as number
      const u = (x: number) => side * x
      const arm = pts(P, [
        [u(17), -139],
        [u(26), -133],
        [u(37 + out), -104],
        [u(36 + out), -96],
        [u(28), -95],
        [u(23), -110],
      ])
      s.blank(p.shape(arm))
      s.stroke(p.shape(arm))
      if (top === "tee")
        s.stroke(
          p.path(
            pts(P, [
              [u(28.5), -118],
              [u(23), -116],
            ]),
          ),
        )
      else if (top !== "overshirt")
        s.stroke(p.line(P(u(32 + out), -100), P(u(35 + out), -97)))
    }
    if (top === "hoodie") {
      const hood = pts(P, [
        [-12, -141],
        [-14.5, -131],
        [-8, -122],
        [8, -122],
        [14.5, -131],
        [12, -141],
      ])
      s.blank(p.shape(hood))
      s.stroke(p.shape(hood))
    }
    if (top === "overshirt") {
      s.stroke(
        p.path(
          pts(P, [
            [-9, -140.5],
            [0, -137],
            [9, -140.5],
          ]),
        ),
      )
      s.stroke(p.line(P(-17, -131), P(17, -131)))
    }
    if (withHead) backOfHead(s, p, P, k, hair)
    else s.stroke(p.ring(P(0, -140.5), [8 * k, 0], [0, 2.6 * k]))
    chair(s, p, P, k, high)
  }

export const visitorSeated = seated(false)
export const personSeated = seated(true)

